                     </div>

                     {/* Create Pet Fallback */}
                     <div className="mb-6 p-4 bg-white rounded-xl border border-slate-200">
                        <h3 className="font-bold text-sm mb-2">Crear nueva mascota</h3>
                        <div className="flex gap-2">
