                        <button onClick={handleLogout} className="w-full py-3 bg-red-100 text-red-600 rounded-xl font-bold">Cerrar Sesión</button>
                        <p className="text-center text-xs text-slate-400 mt-4">v4.0.0 - Supabase + Gemini + Notion</p>
