// --- CONFIGURATION ---
// Priority list: Latest & Fastest -> Stable Backup
const FALLBACK_MODELS = ['gemini-2.0-flash', 'gemini-2.0-flash-lite-preview-02-05'];

const SYSTEM_INSTRUCTION = `
