// --- HELPER: Get API Keys Securely (Multi-Key Support) ---
async function getGeminiApiKeys(settings: SupabaseSettings, accessToken?: string): Promise<string[]> {
    let keys: string[] = [];

    // 1. Try Production Env Vars (Vercel)
    // IMPORTANT: Variables must start with VITE_ to be exposed to the client
    try {
        // @ts-ignore
        if (import.meta.env.VITE_GEMINI_API_KEY) keys.push(import.meta.env.VITE_GEMINI_API_KEY);
        // @ts-ignore
        if (import.meta.env.VITE_GEMINI_API_KEY_BACKUP) keys.push(import.meta.env.VITE_GEMINI_API_KEY_BACKUP);

        // Safety check: Filter out placeholders or empty strings
        keys = keys.filter(k => k && k.length > 10 && !k.includes('placeholder'));
    } catch (e) {
        // Ignore error if env not available
    }

    if (keys.length > 0) {
        console.log(`[Gemini] Usando ${keys.length} claves API encontradas en entorno.`);
        return keys;
    }

    // 2. Fallback: Fetch from Supabase DB
    console.log("[Gemini] Buscando claves en base de datos...");
    if (!settings.supabaseUrl || !settings.supabaseKey) {
        throw new Error("No hay configuración de Supabase para recuperar la clave API.");
    }

    const client = createClient(settings.supabaseUrl, settings.supabaseKey, {
        global: {
            headers: accessToken ? { Authorization: `Bearer ${accessToken}` } : undefined
        }
    });

    const { data, error } = await client
        .from('app_secrets')
        .select('key_name, value')
        .in('key_name', ['GEMINI_API_KEY', 'GEMINI_API_KEY_BACKUP']);

    if (error || !data) {
        console.error("Error fetching API Key:", error);
        throw new Error("No se encontraron claves API de Gemini.");
    }

    const primary = data.find(s => s.key_name === 'GEMINI_API_KEY')?.value;
    const backup = data.find(s => s.key_name === 'GEMINI_API_KEY_BACKUP')?.value;

    if (primary) keys.push(primary);
    if (backup) keys.push(backup);

    // Remove duplicates
    keys = [...new Set(keys)];

    if (keys.length === 0) {
        throw new Error("No hay API KEYs configuradas en 'app_secrets' ni en entorno.");
    }

    console.log(`[Gemini] Encontradas ${keys.length} claves en BD.`);
    return keys;
}

// --- HELPER: Robust Generation with Key Rotation & Fallback ---
async function generateWithFallback(
    apiKeys: string[],
    contents: any,
    baseConfig: any
): Promise<any> {
    let lastError: any;

    // Outer Loop: Rotate through API Keys
    for (let i = 0; i < apiKeys.length; i++) {
        const apiKey = apiKeys[i];
        const isBackup = i > 0;

        // console.log(`[Gemini] Usando Key #${i + 1} (${isBackup ? 'Respaldo' : 'Principal'})...`);
        const ai = new GoogleGenAI({ apiKey });

        // Inner Loop: Rotate through Models
        for (const model of FALLBACK_MODELS) {
            // Retry loop for transient errors (503) within the same model/key combo
            for (let attempt = 0; attempt < 2; attempt++) {
                try {
                    const response = await ai.models.generateContent({
                        model: model,
                        contents: contents,
                        config: baseConfig
                    });
                    return response;
                } catch (error: any) {
                    lastError = error;

                    // Parse Error Message carefully (handle stringified JSON)
                    let status = error.status || error.response?.status;
                    let msg = error.message || "";
                    if (msg.startsWith('{')) {
                        try {
                            const parsed = JSON.parse(msg);
                            if (parsed.error?.code) status = parsed.error.code;
                            if (parsed.error?.message) msg = parsed.error.message;
                        } catch(e) {}
                    }

                    // CRITICAL: If Quota Exceeded (429), break model loop to switch KEY immediately
                    const isQuota = status === 429 || msg.includes('429') || msg.includes('quota') || msg.includes('Quota');

                    if (isQuota) {
                        console.warn(`⚠️ Cuota excedida (429) con Key #${i+1} y Modelo ${model}.`);
                        break; // Breaks Attempt Loop
                    }

                    // Fatal errors (400, 401, 403, 404)
                    if (status === 400 || status === 401 || status === 403 || status === 404) {
                        if (status === 404 && attempt === 0) {
                            // If 404 (Model Not Found), maybe try next model in list, break attempt loop
                            console.warn(`Modelo ${model} no encontrado (404).`);
                            break; 
                        }
                        // Auth error or bad request -> Key might be bad, or request bad. 
                        // If Auth (403/400 key invalid), break to try next key.
                        if (msg.includes('API key')) break; 

                        // Otherwise, it's a prompt error, no use retrying.
                        throw error;
                    }

                    // Transient (503) -> Wait and Retry
                    const isTransient = status === 503 || msg.includes('Overloaded');
                    if (isTransient) {
                        const delay = Math.pow(2, attempt) * 1500; // Increased delay
                        await new Promise(resolve => setTimeout(resolve, delay));
                        continue; 
                    }

                    break; // Unknown error, try next model
                }
            }

            // Logic to break Model Loop if Key is exhausted (429)
            let status = lastError?.status || lastError?.response?.status;
            let msg = lastError?.message || "";
            if (msg.startsWith('{')) { try { const p = JSON.parse(msg); if(p.error) { status = p.error.code; msg = p.error.message; } } catch(e){} }

            if (status === 429 || msg.includes('429') || msg.includes('quota') || msg.includes('Quota')) {
                break; // Break Model Loop -> Continue to next Key in Outer Loop
            }
        }
    }

    console.error("Final Gemini Error:", lastError);
    throw lastError || new Error("Todas las cuentas y modelos de IA fallaron. Revisa tu cuota.");
}


