export const inviteCollaborator = async (settings: SupabaseSettings, petId: string, email: string, accessToken?: string): Promise<{ success: boolean; error?: string }> => {
    const client = createFreshClient(settings, accessToken);
    if (!client) return { success: false, error: "Client error" };

    // NORMALIZE EMAIL: Trim and Lowercase
    const normalizedEmail = email.trim().toLowerCase();
    console.log(`[Invite] Buscando usuario: ${normalizedEmail}`);

    // This RPC must exist in your database to find auth.users IDs from their email safely
    const { data: userId, error: rpcError } = await client.rpc('lookup_user_by_email', { email_input: normalizedEmail });

    if (rpcError) {
        console.error("[Invite] RPC Error:", rpcError);
        return { success: false, error: "Error interno del servidor (RPC)." };
    }

    if (!userId) {
        return { success: false, error: "Usuario no encontrado. Asegúrate de que se haya registrado correctamente." };
    }

    console.log(`[Invite] Usuario encontrado con ID: ${userId}. Añadiendo al grupo...`);

    const { error: insertError } = await client.from('pet_collaborators').insert({ 
        pet_id: petId, 
        user_id: userId, 
        role: 'viewer', 
        permissions: { can_create: true, can_edit: 'own', can_delete: 'own', visible_types: [] } 
    });

    if (insertError) {
        console.error("[Invite] Insert Error:", insertError);
        if (insertError.code === '23505') return { success: false, error: "Este usuario ya está en el equipo." };
        return { success: false, error: insertError.message };
    }

    return { success: true };
};

